:host {
    --code-bg: var(--integration-documentation-blocs-code-background, var(--integration-basic-blocs-surface-text, #0f172a));
    --code-fg: var(--integration-documentation-blocs-code-text, var(--integration-basic-blocs-page-background, #f8fafc));
    --code-header-bg: var(--integration-documentation-blocs-code-header-background, var(--integration-basic-blocs-body-text, #1e293b));
    --code-muted: var(--integration-documentation-blocs-code-muted-text, var(--integration-basic-blocs-secondary-base, #94a3b8));
    --code-accent: var(--integration-documentation-blocs-accent, var(--integration-basic-blocs-primary-base, #6366f1));
    --code-radius: var(--integration-documentation-blocs-radius-panel, var(--integration-basic-blocs-radius-card, .5rem));
    --code-duration: var(--integration-documentation-blocs-motion-duration, 180ms);
    display: block;
    font-family: var(--integration-documentation-blocs-font-body, var(--integration-basic-blocs-font-body, system-ui, sans-serif));
    margin: 1rem 0;
}
.wrapper {
    margin: 0;
    background: var(--code-bg);
    color: var(--code-fg);
    border-radius: var(--code-radius);
    overflow: hidden;
    box-shadow: var(--integration-documentation-blocs-shadow, 0 .5rem 1.5rem rgb(0 0 0 / 25%));
}
.header {
    display: flex;
    align-items: center;
    gap: .75rem;
    padding: .5rem .9rem;
    background: var(--code-header-bg);
    font-size: .78rem;
    color: var(--code-muted);
    border-bottom: 1px solid rgba(255,255,255,.06);
}
.filename { flex: 1; font-weight: 600; }
.filename ::slotted(*) { margin: 0; font: inherit; color: inherit; }
:host(:not(:has([slot="filename"]))) .filename { display: none; }
.lang {
    font-family: var(--integration-documentation-blocs-font-mono, var(--integration-basic-blocs-font-mono, ui-monospace, monospace));
    font-size: .72rem;
    letter-spacing: .05em;
    text-transform: uppercase;
    padding: .1rem .5rem;
    border-radius: 999px;
    background: rgba(255,255,255,.08);
}
:host([language="plain"]) .lang,
:host(:not([language])) .lang { display: none; }
:host([language]) .lang::before { content: attr(data-lang); }
:host([language="ts"]) .lang::before { content: "TS"; }
:host([language="js"]) .lang::before { content: "JS"; }
:host([language="tsx"]) .lang::before { content: "TSX"; }
:host([language="jsx"]) .lang::before { content: "JSX"; }
:host([language="html"]) .lang::before { content: "HTML"; }
:host([language="css"]) .lang::before { content: "CSS"; }
:host([language="json"]) .lang::before { content: "JSON"; }
:host([language="bash"]) .lang::before { content: "Bash"; }
:host([language="python"]) .lang::before { content: "Python"; }
:host([language="go"]) .lang::before { content: "Go"; }
:host([language="rust"]) .lang::before { content: "Rust"; }
:host([language="sql"]) .lang::before { content: "SQL"; }
.copy {
    all: unset;
    box-sizing: border-box;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 2.25rem;
    padding: .25rem .65rem;
    border-radius: 6px;
    font-size: .72rem;
    font-weight: 600;
    background: rgba(255,255,255,.06);
    transition: background var(--code-duration) ease;
}
.copy:hover { background: rgba(255,255,255,.14); }
.copy:focus-visible { outline: 2px solid var(--code-accent); outline-offset: 2px; }
.copy-done { display: none; color: var(--integration-documentation-blocs-terminal-prompt, var(--integration-basic-blocs-success-base, #4ade80)); }
:host([copied]) .copy-label { display: none; }
:host([copied]) .copy-done { display: inline; }
.code-frame {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
}
.line-numbers {
    display: none;
    padding: 1rem .75rem 1rem 1.1rem;
    color: var(--code-muted);
    font-family: var(--integration-documentation-blocs-font-mono, var(--integration-basic-blocs-font-mono, ui-monospace, monospace));
    font-size: .88rem;
    line-height: 1.6;
    text-align: right;
    white-space: pre;
    user-select: none;
}
.code {
    margin: 0;
    padding: 1rem 1.1rem;
    overflow-x: auto;
    font-family: var(--integration-documentation-blocs-font-mono, var(--integration-basic-blocs-font-mono, ui-monospace, monospace));
    font-size: .88rem;
    line-height: 1.6;
    tab-size: 4;
}
.code code { color: inherit; font: inherit; }
.source { white-space: pre; }
.code ::slotted(*) { display: block; font: inherit; color: inherit; margin: 0; white-space: pre-wrap; }
:host([wrap="true"]) .source { white-space: pre-wrap; overflow-wrap: anywhere; }
:host([line-numbers="true"]) .code-frame { grid-template-columns: auto minmax(0, 1fr); }
:host([line-numbers="true"]) .line-numbers { display: block; }
:host([theme="light"]) {
    --code-bg: var(--integration-documentation-blocs-subtle-surface);
    --code-fg: var(--integration-documentation-blocs-heading-text);
    --code-header-bg: var(--integration-documentation-blocs-border);
    --code-muted: var(--integration-documentation-blocs-muted-text);
}
@media (prefers-reduced-motion: reduce) { :host { --code-duration: 0ms; } }

