:host {
    --pn-border: var(--integration-documentation-blocs-border, var(--integration-basic-blocs-surface-border, #e2e8f0));
    --pn-accent: var(--integration-documentation-blocs-accent, var(--integration-basic-blocs-primary-base, #4f46e5));
