}

.wrap {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

::slotted(a) {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 1rem 1.25rem;
    border: 1px solid var(--pn-border);
    border-radius: var(--integration-documentation-blocs-radius-panel, var(--integration-basic-blocs-radius-card, .5rem));
    color: inherit;
    font-size: 1rem;
    font-weight: 600;
    text-decoration: none;
    transition: border-color var(--pn-duration) ease, transform var(--pn-duration) ease, box-shadow var(--pn-duration) ease;
}

::slotted(a[slot="previous"])::before { content: "←"; color: var(--pn-muted); }
::slotted(a[slot="next"]) { justify-content: flex-end; text-align: right; }
::slotted(a[slot="next"])::after { content: "→"; color: var(--pn-muted); }
::slotted(a:hover) { border-color: var(--pn-accent); transform: translateY(-2px); box-shadow: var(--integration-documentation-blocs-shadow, 0 8px 20px -12px rgb(0 0 0 / 15%)); }
