                        "type": "select",
                        "label": "Heading levels",
                        "attribute": "levels",
                        "options": [
                            {
                                "label": "H2 only",
                                "value": "h2",
                            },
                            {
                                "label": "H2 and H3",
                                "value": "h2-h3",
                            },
                            {
                                "label": "H2, H3 and H4",
